 for n,ib,ob in re.findall(r'Demo pair (\d+) input \((\d+x\d+)\):\n(.*?)\nDemo pair \1 output \((\d+x\d+)\):\n(.*?)(?=\n\nSame instance|\Z)',c,re.S):
  def grid(txt):return [list(map(int,z.split())) for z in txt.strip().splitlines()]
